83	export function openCatalog(databasePath: string) {
84	  if (databasePath !== ":memory:") mkdirSync(dirname(databasePath), { recursive: true });
85	  const db = new DatabaseSync(databasePath);
86	  db.exec(`
87	    PRAGMA foreign_keys = ON;
88	    PRAGMA journal_mode = WAL;
89	    CREATE TABLE IF NOT EXISTS polls (
90	      id TEXT PRIMARY KEY, title TEXT NOT NULL, summary TEXT NOT NULL,
91	      description TEXT NOT NULL, organizer TEXT NOT NULL, status TEXT NOT NULL,
92	      published_at TEXT NOT NULL, closes_at TEXT NOT NULL, options_json TEXT NOT NULL
93	    );
94	    CREATE TABLE IF NOT EXISTS members (
95	      commitment TEXT PRIMARY KEY, position INTEGER NOT NULL UNIQUE
96	    );
97	    CREATE TABLE IF NOT EXISTS votes (
98	      id TEXT PRIMARY KEY,
99	      poll_id TEXT NOT NULL REFERENCES polls (id),
100	      option_id TEXT NOT NULL,
101	      nullifier TEXT NOT NULL,
102	      accepted_at TEXT NOT NULL
103	    );
104	    CREATE UNIQUE INDEX IF NOT EXISTS votes_poll_nullifier ON votes (poll_id, nullifier);
105	    CREATE TABLE IF NOT EXISTS group_versions (
106	      poll_id TEXT NOT NULL REFERENCES polls (id),
107	      version INTEGER NOT NULL,
108	      commitments_json TEXT NOT NULL,
109	      merkle_root TEXT NOT NULL,
110	      created_at TEXT NOT NULL,
111	      PRIMARY KEY (poll_id, version)
112	    );
113	    CREATE INDEX IF NOT EXISTS group_versions_root ON group_versions (poll_id, merkle_root);
114	    CREATE TABLE IF NOT EXISTS audit_events (
115	      id TEXT PRIMARY KEY,
116	      action TEXT NOT NULL,
117	      poll_id TEXT NOT NULL,
118	      result TEXT NOT NULL,
119	      at TEXT NOT NULL,
120	      details_json TEXT NOT NULL
121	    );
122	    CREATE INDEX IF NOT EXISTS audit_events_time ON audit_events (at DESC, id DESC);
123	  `);
124	  // Migrate pre-versioning databases: add the group columns to existing polls.
125	  const pollColumns = new Set((db.prepare("PRAGMA table_info(polls)").all() as { name: string }[]).map(column => column.name));
126	  if (!pollColumns.has("group_version")) db.exec("ALTER TABLE polls ADD COLUMN group_version INTEGER NOT NULL DEFAULT 1");
127	  if (!pollColumns.has("frozen_version")) db.exec("ALTER TABLE polls ADD COLUMN frozen_version INTEGER");
128	  if (!pollColumns.has("snapshot_json")) db.exec("ALTER TABLE polls ADD COLUMN snapshot_json TEXT");
129	
130	  const existing = db.prepare("SELECT count(*) AS count FROM polls").get() as { count: number };
131	  if (existing.count === 0) {
132	    const seed = JSON.parse(readFileSync(new URL("../fixtures/catalog.json", import.meta.url), "utf8")) as CatalogSeed;
133	    db.exec("BEGIN");
134	    try {
135	      const insertPoll = db.prepare("INSERT INTO polls (id, title, summary, description, organizer, status, published_at, closes_at, options_json) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
136	      for (const poll of seed.polls) insertPoll.run(poll.id, poll.title, poll.summary, poll.description, poll.organizer, poll.status, poll.publishedAt, poll.closesAt, JSON.stringify(poll.options));
137	      const insertMember = db.prepare("INSERT INTO members VALUES (?, ?)");
138	      seed.memberCommitments.forEach((commitment, index) => insertMember.run(commitment, index));
139	      db.exec("COMMIT");
140	    } catch (error) { db.exec("ROLLBACK"); db.close(); throw error; }
141	  }
142	  // Legacy databases only ever knew the "open" state: normalize any poll whose
143	  // status is not part of the lifecycle to open, so old issues migrate forward.
144	  db.exec(`UPDATE polls SET status = 'open' WHERE status NOT IN ('draft', 'open', 'closed', 'archived')`);
145	  // Snapshot the legacy member list as immutable version 1 for every poll that
146	  // has no versions yet (fresh seeds and databases migrated from before
147	  // versioned groups). The snapshot, its Merkle root and the version number
148	  // are persisted together so all three stay consistent across restarts.
149	  const versioned = db.prepare("SELECT count(*) AS count FROM group_versions").get() as { count: number };
150	  if (versioned.count === 0) {
151	    const commitments = members();
152	    if (commitments.length > 0) {
153	      const merkleRoot = merkleRootOf(commitments);
154	      const createdAt = new Date().toISOString();
155	      const insertVersion = db.prepare("INSERT INTO group_versions (poll_id, version, commitments_json, merkle_root, created_at) VALUES (?, 1, ?, ?, ?)");
156	      const pollIds = db.prepare("SELECT id FROM polls").all() as { id: string }[];
157	      db.exec("BEGIN");
158	      try {
159	        for (const poll of pollIds) insertVersion.run(poll.id, JSON.stringify(commitments), merkleRoot, createdAt);
160	        // Polls that already accepted votes are frozen on version 1, matching
161	        // the freeze-on-first-vote rule applied to new votes.
162	        db.exec("UPDATE polls SET frozen_version = 1 WHERE frozen_version IS NULL AND id IN (SELECT DISTINCT poll_id FROM votes)");
163	        db.exec("COMMIT");
164	      } catch (error) { db.exec("ROLLBACK"); db.close(); throw error; }
165	    }
166	  }
167	  // Backfill the close snapshot for polls that closed (or archived) before
168	  // snapshots existed. The version is the poll's current group version and the
169	  // counts come from the ballots; closedAt falls back from the successful
170	  // close audit event, to the last accepted vote, to the deadline. Written
171	  // once here, the snapshot is fixed from then on.
172	  const missingSnapshots = db.prepare("SELECT id FROM polls WHERE status IN ('closed', 'archived') AND snapshot_json IS NULL").all() as { id: string }[];
173	  if (missingSnapshots.length > 0) {
174	    db.exec("BEGIN");
175	    try {
176	      for (const { id } of missingSnapshots) {
177	        const closeAudit = (db.prepare("SELECT at, details_json FROM audit_events WHERE poll_id = ? AND action = 'poll_status_change' AND result = 'success' ORDER BY at ASC, id ASC").all(id) as { at: string; details_json: string }[])
178	          .find(event => (JSON.parse(event.details_json) as { to?: string }).to === "closed");
179	        const lastVote = db.prepare("SELECT accepted_at FROM votes WHERE poll_id = ? ORDER BY accepted_at DESC, id DESC LIMIT 1").get(id) as { accepted_at: string } | undefined;
180	        const row = pollRow(id);
181	        if (!row) continue;
182	        const closedAt = new Date(Date.parse(closeAudit?.at ?? lastVote?.accepted_at ?? row.closes_at)).toISOString();
183	        writeSnapshot(id, closedAt);
184	      }
185	      db.exec("COMMIT");
186	    } catch (error) { db.exec("ROLLBACK"); db.close(); throw error; }
187	  }
