214	test("audit query filters, paginates and validates the time range", async () => {
215	  await withTempDb(async path => {
216	    const { server, base } = await serve(path, ADMIN_TOKEN);
217	    try {
218	      // Generate a handful of events across two polls, successes and failures.
219	      for (const id of ["audit-a", "audit-b"]) {
220	        const created = await fetch(`${base}/api/polls`, {
221	          method: "POST", headers: adminHeaders,
222	          body: JSON.stringify({ ...makePoll(id), commitments: ["11", "22"] })
223	        });
224	        assert.equal(created.status, 201);
225	      }
226	      await fetch(`${base}/api/polls/audit-a/status`, { method: "POST", headers: adminHeaders, body: JSON.stringify({ status: "open", expectedStatus: "draft" }) });
227	      await fetch(`${base}/api/polls/audit-a/status`, { method: "POST", headers: adminHeaders, body: JSON.stringify({ status: "archived", expectedStatus: "open" }) });
228	
229	      const audit = async (query: string) => {
230	        const response = await fetch(`${base}/api/admin/audit${query}`, { headers: { "X-Admin-Token": ADMIN_TOKEN } });
231	        return { status: response.status, body: await response.json() as AuditPage & { error?: string } };
232	      };
233	
234	      // Default page: newest first, page 1 with the default page size.
235	      const all = await audit("");
236	      assert.equal(all.status, 200);
237	      assert.equal(all.body.page, 1);
238	      assert.equal(all.body.pageSize, 50);
239	      assert.equal(all.body.total, all.body.events.length);
240	      assert.equal(all.body.totalPages, 1);
241	      const timestamps = all.body.events.map(event => Date.parse(event.at));
242	      assert.deepEqual(timestamps, [...timestamps].sort((x, y) => y - x));
243	
244	      // Exact-match filters compose.
245	      const byPoll = await audit("?pollId=audit-a");
246	      assert.ok(byPoll.body.events.length > 0);
247	      assert.ok(byPoll.body.events.every(event => event.pollId === "audit-a"));
248	      const byAction = await audit("?pollId=audit-a&action=poll_create");
249	      assert.deepEqual(byAction.body.events.map(event => event.action), ["poll_create"]);
250	      const failures = await audit("?result=failure");
251	      assert.ok(failures.body.events.length > 0);
252	      assert.ok(failures.body.events.every(event => event.result === "failure"));
253	
254	      // from/to are ISO8601 and inclusive at both ends.
255	      const pivot = all.body.events[1].at;
256	      const around = await audit(`?from=${encodeURIComponent(pivot)}&to=${encodeURIComponent(pivot)}`);
257	      assert.ok(around.body.events.length >= 1);
258	      assert.ok(around.body.events.every(event => event.at === pivot));
259	      const bounded = await audit(`?from=${encodeURIComponent(all.body.events[all.body.events.length - 1].at)}&to=${encodeURIComponent(all.body.events[0].at)}`);
260	      assert.equal(bounded.body.total, all.body.total);
261	
262	      // Invalid or inverted ranges are 400.
263	      assert.equal((await audit("?from=not-a-date")).status, 400);
264	      assert.equal((await audit("?to=2026-13-01T00:00:00Z")).status, 400);
265	      assert.equal((await audit("?from=2026-09-20T00:00:00Z&to=2026-09-19T00:00:00Z")).status, 400);
266	
267	      // Only strict timezone-aware ISO 8601 instants pass: values Date.parse
268	      // accepts loosely are rejected outright.
269	      const loose = [
270	        "2026-09-20",                                  // date-only
271	        "2026-09-20 10:00:00Z",                       // space separator
272	        "2026-09-20T10:00:00",                        // no time zone
273	        "2026-09-20T10:00Z",                          // no seconds
274	        "2026/09/20T10:00:00Z",                       // wrong separator
275	        "2026-02-29T00:00:00Z",                       // impossible calendar date (2026 is common)
276	        "2026-04-31T00:00:00Z",                       // April has 30 days
277	        "2026-09-20T24:00:00Z",                       // out-of-range hour
278	        "Tue Sep 20 2026 10:00:00 GMT",               // free-form Date.parse text
279	        "2026-09-20T10:00:00+24:00"                   // out-of-range offset
280	      ];
281	      for (const value of loose) {
282	        assert.equal((await audit(`?from=${encodeURIComponent(value)}`)).status, 400, `from=${value}`);
283	        assert.equal((await audit(`?to=${encodeURIComponent(value)}`)).status, 400, `to=${value}`);
284	      }
285	
286	      // Explicit non-UTC offsets are accepted and normalized to the same UTC
287	      // instant; the pivot event stays reachable through the offset bound.
288	      const pivotOffset = pivot.replace("Z", "+00:00");
289	      const viaOffset = await audit(`?from=${encodeURIComponent(pivotOffset)}`);
290	      assert.equal(viaOffset.status, 200);
291	      assert.ok(viaOffset.body.events.some(event => event.at === pivot));
292	
293	      // Pagination: pageSize capped at 200, pages line up with the total.
294	      const capped = await audit("?pageSize=500");
295	      assert.equal(capped.body.pageSize, 200);
296	      const paged = await audit("?pageSize=2&page=2");
297	      assert.equal(paged.body.page, 2);
298	      assert.equal(paged.body.pageSize, 2);
299	      assert.equal(paged.body.events.length, 2);
300	      assert.equal(paged.body.totalPages, Math.ceil(paged.body.total / 2));
301	      assert.deepEqual(paged.body.events.map(event => event.id), all.body.events.slice(2, 4).map(event => event.id));
302	      assert.equal((await audit("?page=0")).status, 400);
303	      assert.equal((await audit("?pageSize=abc")).status, 400);
304	
305	      // Still admin-only.
306	      assert.equal((await fetch(`${base}/api/admin/audit`)).status, 401);
307	    } finally { await stop(server); }
308	  });
309	});
