59	test("every /api answer gets a fresh server-generated X-Request-Id and spoofs are ignored", async () => {
60	  const { server, base, lines } = await serve();
61	  try {
62	    const first = await fetch(`${base}/api/health`);
63	    const id1 = first.headers.get("x-request-id");
64	    assert.match(id1 ?? "", /^[0-9a-f-]{36}$/);
65	
66	    const second = await fetch(`${base}/api/health`, { headers: { "X-Request-Id": "spoofed-id" } });
67	    const id2 = second.headers.get("x-request-id");
68	    assert.notEqual(id2, "spoofed-id");
69	    assert.notEqual(id1, id2);
70	
71	    // Error answers carry it too.
72	    const missing = await fetch(`${base}/api/polls/nope`);
73	    assert.equal(missing.headers.get("x-request-id")?.length, 36);
74	
75	    // The log line uses the same server id.
76	    assert.ok(lines.some(line => JSON.parse(line).requestId === id1));
77	  } finally { await stop(server); }
78	});
