1	import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
2	import { existsSync, readFileSync, statSync } from "node:fs";
3	import { extname, resolve, sep } from "node:path";
4	import { timingSafeEqual } from "node:crypto";
5	import { verifyProof, type SemaphoreProof } from "@semaphore-protocol/proof";
6	import { openCatalog, STATUSES, type AuditQuery, type GroupOperation, type NewPollInput } from "./store.ts";
7	import { isCommitment, isProofPayload, terminateProverWorkers, textToField } from "./voting.ts";
8	import { parseInstant } from "./time.ts";
9	import {
10	  MetricsRegistry, decisionFor, emitRequestLog, newObsContext, newRequestId, outcomeFor, sanitizeErrorCode,
11	  type ObsContext, type RequestLogEntry
12	} from "./observability.ts";
13	import type { AuditEvent, PollStatus } from "./types.ts";
14	
15	const MAX_BODY_BYTES = 1_000_000;
16	
17	export interface AppOptions {
18	  /** When unset (or empty) every administrative request is refused with 401. */
19	  adminToken?: string;
20	  /** Sink for single-line JSON access logs; defaults to stdout. A throwing sink is swallowed. */
21	  logSink?: (line: string) => void;
22	  /** Proof verification implementation; defaults to the Semaphore verifier. */
23	  verifyProofImpl?: (proof: SemaphoreProof) => Promise<boolean>;
24	  /** SQLite readiness probe; defaults to a SELECT 1 against the catalog. */
25	  sqlitePing?: () => void;
26	}
27	
28	function readBody(request: IncomingMessage): Promise<string> {
29	  return new Promise((resolvePromise, rejectPromise) => {
30	    const chunks: Buffer[] = [];
31	    let size = 0;
32	    request.on("data", (chunk: Buffer) => {
33	      size += chunk.length;
34	      if (size > MAX_BODY_BYTES) { rejectPromise(new Error("body_too_large")); request.destroy(); return; }
35	      chunks.push(chunk);
36	    });
37	    request.on("end", () => resolvePromise(Buffer.concat(chunks).toString("utf8")));
38	    request.on("error", rejectPromise);
39	  });
40	}
41	
42	function isNonEmptyString(value: unknown, maxLength = 2000): value is string {
43	  return typeof value === "string" && value.trim().length > 0 && value.length <= maxLength;
44	}
45	
46	export function createApp(databasePath: string, publicPath = resolve("dist/public"), options: AppOptions = {}) {
47	  const catalog = openCatalog(databasePath);
48	  const adminToken = options.adminToken && options.adminToken.length > 0 ? options.adminToken : undefined;
49	  const logSink = options.logSink ?? ((line: string) => process.stdout.write(line));
50	  const verify = options.verifyProofImpl ?? verifyProof;
51	  const sqlitePing = options.sqlitePing ?? (() => catalog.ping());
52	  const metrics = new MetricsRegistry();
53	  // The proof engine starts healthy; its first verification proves it. A
54	  // verification failure latches an error that /api/ready reports until a
55	  // later verification succeeds and clears it.
56	  let proverFailure = false;
57	  let proverUsed = false;
58	  const mime: Record<string, string> = { ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".css": "text/css; charset=utf-8", ".svg": "image/svg+xml", ".json": "application/json; charset=utf-8" };
