1	import { randomUUID } from "node:crypto";
2	
3	/**
4	 * Privacy-safe runtime observability: per-request correlation ids, single-line
5	 * structured access logs and in-memory metrics. Nothing here ever sees request
6	 * bodies, query strings, tokens, commitments, proofs, nullifiers, receipt ids
7	 * or poll ids — only a fixed, low-cardinality operation vocabulary and the
8	 * stable error codes the API already returns.
9	 */
10	
11	export type Outcome = "success" | "rejected" | "unauthorized" | "error";
12	
13	/** Per-request scratch space the handler fills while routing. */
14	export interface ObsContext {
15	  /** Stable operation name (fixed vocabulary, never derived from ids/paths). */
16	  operation: string;
17	  /** Status code actually sent, captured from the json() choke point. */
18	  statusCode: number;
19	  /** Stable machine-readable error code, when the response failed. */
20	  errorCode?: string;
21	  /** Skip the log line and metrics record (non-API assets and the metrics endpoint itself). */
22	  skip: boolean;
23	  /** Whether to attach X-Request-Id to the response (every /api answer, including metrics). */
24	  header: boolean;
25	}
26	
27	export function newRequestId(): string {
28	  return randomUUID();
29	}
30	
31	export function newObsContext(): ObsContext {
32	  // Static assets are outside the /api observability contract; the handler
33	  // opts in when routing under /api.
34	  return { operation: "static", statusCode: 0, skip: true, header: false };
35	}
36	
37	const ERROR_CODE_PATTERN = /^[a-z0-9_]{1,64}$/;
38	
39	/**
40	 * Only codes from the API's own stable vocabulary are allowed through; this
41	 * guards against user-controlled text ever reaching the log or metrics.
42	 */
43	export function sanitizeErrorCode(code: unknown): string | undefined {
44	  return typeof code === "string" && ERROR_CODE_PATTERN.test(code) ? code : undefined;
45	}
46	
47	export function outcomeFor(statusCode: number): Outcome {
48	  if (statusCode === 401) return "unauthorized";
49	  if (statusCode >= 500) return "error";
50	  if (statusCode >= 200 && statusCode < 300) return "success";
51	  return "rejected";
52	}
53	
54	/**
55	 * Votes and membership changes are adjudicated inside an immediate SQLite
56	 * transaction; their log line/metrics carry the low-cardinality admission
57	 * decision of that transaction: "accepted" on success, "conflict" when the
58	 * request raced or clashed with persisted state (409), "rejected" for other
59	 * client failures, plus "unauthorized"/"error". The precise conflict reason
60	 * stays available through errorCode without inflating this label's cardinality.
61	 */
62	export function decisionFor(operation: string, statusCode: number, outcome: Outcome): string | undefined {
63	  if (operation !== "vote_submit" && operation !== "group_change") return undefined;
64	  if (outcome === "unauthorized") return "unauthorized";
65	  if (outcome === "error") return "error";
66	  if (statusCode >= 200 && statusCode < 300) return "accepted";
67	  if (statusCode === 409) return "conflict";
68	  return "rejected";
69	}
70	
71	export interface RequestLogEntry {
72	  at: string;
73	  requestId: string;
74	  operation: string;
75	  statusCode: number;
76	  outcome: Outcome;
77	  durationMs: number;
78	  errorCode?: string;
79	  decision?: string;
80	}
81	
82	interface MetricsBucket {
83	  count: number;
84	  sumMs: number;
85	  maxMs: number;
86	}
87	
88	export interface MetricsRow {
89	  operation: string;
90	  statusCode: number;
91	  errorCode: string | null;
92	  decision: string | null;
93	  count: number;
94	  sumMs: number;
95	  maxMs: number;
96	}
97	
98	export interface MetricsReport {
99	  startedAt: string;
100	  metrics: MetricsRow[];
101	}
102	
103	/**
104	 * Process-local, non-persistent counters. Node executes event-loop turns to
105	 * completion, so record() (called from the response "finish" event) never
106	 * interleaves: concurrent requests cannot lose or corrupt an update.
107	 */
108	export class MetricsRegistry {
109	  readonly startedAt: string;
110	  private readonly buckets = new Map<string, MetricsBucket>();
111	
112	  constructor(now: Date = new Date()) {
113	    this.startedAt = now.toISOString();
114	  }
115	
116	  record(entry: RequestLogEntry): void {
117	    // Empty segments (not the string "null") key buckets that report JSON null.
118	    const errorCode = entry.errorCode ?? "";
119	    const decision = decisionFor(entry.operation, entry.statusCode, entry.outcome) ?? "";
120	    const key = `${entry.operation}|${entry.statusCode}|${errorCode}|${decision}`;
121	    const bucket = this.buckets.get(key);
122	    if (bucket) {
123	      bucket.count += 1;
124	      bucket.sumMs += entry.durationMs;
125	      if (entry.durationMs > bucket.maxMs) bucket.maxMs = entry.durationMs;
126	    } else {
127	      this.buckets.set(key, { count: 1, sumMs: entry.durationMs, maxMs: entry.durationMs });
128	    }
129	  }
130	
131	  snapshot(): MetricsReport {
132	    const rows: MetricsRow[] = [];
133	    for (const [key, bucket] of this.buckets) {
134	      const [operation, statusText, errorCode, decision] = key.split("|") as [string, string, string, string];
135	      rows.push({
136	        operation,
137	        statusCode: Number(statusText),
138	        errorCode: errorCode ? errorCode : null,
139	        decision: decision ? decision : null,
140	        count: bucket.count,
141	        sumMs: bucket.sumMs,
142	        maxMs: bucket.maxMs
143	      });
144	    }
145	    rows.sort((a, b) =>
146	      a.operation.localeCompare(b.operation) ||
147	      a.statusCode - b.statusCode ||
148	      (a.errorCode ?? "").localeCompare(b.errorCode ?? "") ||
